const body = $input.first().json.body ?? $input.first().json;
const msg = body.message || body;
const type = msg.type || 'unknown';
let toolCalls = [];
if (type === 'tool-calls') {
  const raw = msg.toolCallList || msg.toolCalls || [];
  toolCalls = raw.map(tc => {
    const fn = tc.function || tc;
    let args = fn.arguments;
    if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }
    return { toolCallId: tc.id || tc.toolCallId, name: fn.name, args: args || {} };
  });
}
return [{ json: { messageType: type, toolCalls, raw: msg } }];

const cfg = $('Load Clinic Config').first().json;
const msg = $('Parse Vapi Message').first().json.raw;
const call = msg.call || {};
const customerPhone = (call.customer && call.customer.number) || (msg.customer && msg.customer.number) || '';
const summary = msg.summary || (msg.analysis && msg.analysis.summary) || '';
const transcript = msg.transcript || '';
const endedReason = msg.endedReason || '';
return [{ json: { sheet_id: cfg.sheet_id, test_mode: cfg.test_mode, timestamp: $now.toISO(), session_id: call.id || '', phone: customerPhone, summary, transcript, endedReason } }];

const d = $json; const patient_key = (d.phone || '').replace(/\D/g, '');
if (!patient_key) return [];
return [{ json: { sheet_id: d.sheet_id, patient_key, last_interaction: d.timestamp, last_conversation_summary: (d.test_mode ? '[TEST] ' : '') + (d.summary || 'Phone call'), status: 'Active' } }];

const cfg = $('Load Clinic Config').first().json;
const clinic = { clinic_name: cfg.clinic_name, staff_email: cfg.staff_email, staff_phone: cfg.staff_phone, twilio_from: cfg.twilio_from, sheet_id: cfg.sheet_id, pinecone_index: cfg.pinecone_index, pinecone_namespace: cfg.pinecone_namespace, pinecone_min_score: cfg.pinecone_min_score, clinic_calendar: cfg.clinic_calendar, appointment_duration_min: cfg.appointment_duration_min, change_cutoff_hours: cfg.change_cutoff_hours, sms_enabled_patient: cfg.sms_enabled_patient, sms_enabled_staff: cfg.sms_enabled_staff, test_mode: cfg.test_mode };
const parsed = $('Parse Vapi Message').first().json;
return parsed.toolCalls.map(tc => ({ json: { toolCallId: tc.toolCallId, name: tc.name, args: tc.args, clinic } }));

const orig = $('Route Tool').item.json;
const args = orig.args; const clinic = orig.clinic;
const phone = (args.phone || '').replace(/\D/g, ''); const email = (args.email || '').trim().toLowerCase();
const rows = $input.all().map(i => i.json).filter(r => r && (r.patient_key || r.phone || r.email));
let match = null;
if (phone && phone.length >= 7) { match = rows.find(r => String(r.phone || '').replace(/\D/g, '') === phone); }
if (!match && email) { match = rows.find(r => String(r.email || '').trim().toLowerCase() === email); }
const found = !!match;
const patient_type = found ? 'Existing' : 'New';
const first_name = found ? match.first_name : (args.first_name || '');
const last_name = found ? match.last_name : (args.last_name || '');
const patient_key = phone || email || '';
const created_at = (match && match.created_at) || $now.toISO();
const record = { sheet_id: clinic.sheet_id, patient_key, created_at, last_interaction: $now.toISO(), first_name: first_name || args.first_name || '', last_name: last_name || args.last_name || '', email: args.email || (match ? match.email : '') || '', phone: args.phone || (match ? match.phone : '') || '', service_required: args.service || (match ? match.service_required : '') || '', patient_type, last_conversation_summary: (clinic.test_mode ? '[TEST] ' : '') + 'Phone call check-in', status: 'Active', notes: '' };
return [{ json: { toolCallId: orig.toolCallId, found, patient_type, first_name, last_name, patient_key, clinic, _record: record } }];

const orig = $('Route Tool').item.json;
const events = $input.all().map(i => i.json).filter(e => e && (e.id || e.start));
const available = events.length === 0;
return [{ json: { toolCallId: orig.toolCallId, result: { available } } }];

const orig = $('Route Tool').item.json; const args = orig.args; const clinic = orig.clinic;
const dur = args.duration_min || clinic.appointment_duration_min || 60;
const start = args.start_iso; const end = DateTime.fromISO(start).plus({ minutes: dur }).toISO();
const events = $input.all().map(i => i.json).filter(e => e && (e.id || e.start));
const free = events.length === 0;
const name = `${args.first_name || ''} ${args.last_name || ''}`.trim();
return [{ json: { toolCallId: orig.toolCallId, args, clinic, free, start, end, summary: `(TENTATIVE) Dental appt - ${name}`, description: `Tentative booking via voice assistant. Service: ${args.service || '-'}. Phone: ${args.phone || '-'}. Email: ${args.email || '-'}. NOT staff-confirmed.` } }];

const d = $('BA_Decide').item.json;
const when = DateTime.fromISO(d.start).toFormat('cccc, LLL d, t');
return [{ json: { toolCallId: d.toolCallId, result: { booked: true, tentative: true, message: `Tentatively held ${when}. Our team will confirm it shortly.` } } }];

const d = $json;
const when = DateTime.fromISO(d.start).toFormat('cccc, LLL d, t');
return [{ json: { toolCallId: d.toolCallId, result: { booked: false, tentative: false, message: `${when} isn't available. Could you share another date and time?` } } }];

const orig = $('Route Tool').item.json; const args = orig.args; const clinic = orig.clinic;
const email = (args.email || '').toLowerCase(); const phone = (args.phone || '').replace(/\D/g, '');
const events = $input.all().map(i => i.json);
let match = null;
for (const e of events) { const att = JSON.stringify(e.attendees || '').toLowerCase(); const blob = `${e.summary||''} ${e.description||''}`.toLowerCase();
  if (email && (att.includes(email) || blob.includes(email))) { match = e; break; }
  if (phone && blob.replace(/\D/g,'').includes(phone)) { match = e; break; } }
const cutoff = clinic.change_cutoff_hours || 48;
let found = !!match, within = false, eventId = '', startIso = '';
if (match) { startIso = (match.start && (match.start.dateTime || match.start.date)) || match.start || ''; eventId = match.id || '';
  try { const hrs = DateTime.fromISO(startIso).diff($now, 'hours').hours; within = hrs < cutoff; } catch (e) { within = true; } }
const action = args.action === 'reschedule' ? 'reschedule' : 'cancel';
const newStart = args.new_start_iso || '';
const dur = clinic.appointment_duration_min || 60;
const newEnd = newStart ? DateTime.fromISO(newStart).plus({ minutes: dur }).toISO() : '';
const needsStaff = within || !found || (action === 'reschedule' && !newStart);
return [{ json: { toolCallId: orig.toolCallId, args, clinic, found, within, needsStaff, eventId, startIso, action, newStart, newEnd } }];

const d = $json;
const cutoffTxt = d.clinic.change_cutoff_hours;
const reason = d.within ? `within our ${cutoffTxt}-hour change window` : (!d.found ? "we couldn't locate the appointment automatically" : 'no new time was given for the reschedule');
return [{ json: { toolCallId: d.toolCallId, result: { needs_staff: true, message: `Because that's ${reason}, our team will handle this directly and confirm with you shortly.` } } }];

const d = $('CR_Compute').item.json;
const when = d.startIso ? DateTime.fromISO(d.startIso).toFormat('cccc, LLL d, t') : 'your appointment';
return [{ json: { toolCallId: d.toolCallId, result: { needs_staff: false, message: `Done - I've cancelled ${when}. Let us know if you need anything else.` } } }];

const d = $('CR_Compute').item.json;
const when = d.newStart ? DateTime.fromISO(d.newStart).toFormat('cccc, LLL d, t') : 'the new time';
return [{ json: { toolCallId: d.toolCallId, result: { needs_staff: false, message: `Done - I've moved your appointment to ${when} (tentatively). Our team will confirm.` } } }];

const orig = $('Route Tool').item.json; const args = orig.args; const clinic = orig.clinic;
const blob = (args.issue_summary || '').toLowerCase();
const redFlags = ['swelling','swollen','breath','breathing','uncontrolled','fever','faint','injury','accident','knocked out'];
const hasRedFlag = redFlags.some(k => blob.includes(k));
let message = "I'm sorry you're dealing with that. I've flagged this to our clinic team right away so someone can follow up quickly.";
if (hasRedFlag) { message += ' If you have severe swelling, trouble breathing, uncontrolled bleeding, a high fever, or a serious injury, please seek urgent or emergency medical care immediately.'; }
return [{ json: { toolCallId: orig.toolCallId, args, clinic, message, hasRedFlag } }];

const orig = $('Route Tool').item.json;
const docs = $input.all();
let maxScore = 0; const chunks = [];
for (const d of docs) { const j = d.json || {}; const s = j.score ?? j.document?.score ?? j.metadata?.score ?? null; if (typeof s === 'number' && s > maxScore) maxScore = s; const t = j.pageContent ?? j.document?.pageContent ?? j.text ?? ''; if (t) chunks.push(t); }
const found = maxScore > 0 ? (maxScore >= orig.clinic.pinecone_min_score) : (chunks.length > 0);
return [{ json: { toolCallId: orig.toolCallId, clinic: orig.clinic, args: orig.args, found, maxScore, knowledge: chunks.slice(0, 5).join('\n---\n') } }];
